{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.knot_master as WITH inward_data AS ( SELECT SKU_GROUP, MIN(DATE) AS first_inward_date FROM snitch_db.maplemonk.knot_inventory_report GROUP BY SKU_GROUP ), inventory_first_10_days AS ( SELECT i.SKU_GROUP, SUM(ir.OPENING_INVENTORY) AS opening_inventory_first_10_days FROM inward_data i JOIN snitch_db.maplemonk.knot_inventory_report ir ON i.SKU_GROUP = ir.SKU_GROUP AND ir.DATE BETWEEN i.first_inward_date AND DATEADD(DAY, 10, i.first_inward_date) GROUP BY i.SKU_GROUP ), sales_after_inward AS ( SELECT k.SKU_GROUP, i.first_inward_date, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 7, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_7, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 15, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_15, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 30, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_30 FROM snitch_db.maplemonk.knot_fact_item k JOIN inward_data i ON k.SKU_GROUP = i.SKU_GROUP GROUP BY k.SKU_GROUP, i.first_inward_date ), str_final AS ( SELECT s.SKU_GROUP, DIV0(s.sales_day_7, q.opening_inventory_first_10_days) AS STR_DAY_7, DIV0(s.sales_day_15, q.opening_inventory_first_10_days) AS STR_DAY_15, DIV0(s.sales_day_30, q.opening_inventory_first_10_days) AS STR_DAY_30 FROM sales_after_inward s JOIN inventory_first_10_days q ON s.SKU_GROUP = q.SKU_GROUP ), knot_group_data AS ( SELECT sku_group, order_date, SUM(sold_quantity) AS suborder_quantity, SUM(return_quantity) AS return_quantity, MAX(selling_price) AS mrp, SUM(selling_price) AS sp FROM ( SELECT SKU_GROUP AS sku_group, CAST(ORDER_DATE AS DATE) AS order_date, TOTAL_QUANTITY AS sold_quantity, RETURN_QUANTITY AS return_quantity, SELLING_PRICE FROM snitch_db.maplemonk.knot_fact_item ) sub GROUP BY sku_group, order_date ), first_order_dates AS ( SELECT sku_group, MIN(order_date) AS first_order_date, MAX(order_date) AS last_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MAX(order_date), CURRENT_DATE) AS days_since_last_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM knot_group_data GROUP BY sku_group ), total_sales AS ( SELECT k.sku_group, f.first_order_date, f.last_order_date, f.days_since_first_order, f.days_since_last_order, f.total_days_sold, MAX(mrp) AS mrp, DIV0(SUM(sp), SUM(suborder_quantity)) AS asp, SUM(return_quantity) AS total_returns, SUM(suborder_quantity) AS total_sales, SUM(CASE WHEN order_date <= DATEADD(DAY, 30, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN order_date <= DATEADD(DAY, 15, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN order_date <= DATEADD(DAY, 7, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN order_date <= DATEADD(DAY, 90, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN order_date <= DATEADD(DAY, 60, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN order_date <= DATEADD(DAY, 180, f.first_order_date) THEN suborder_quantity ELSE 0 END) AS sales_first_180_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 30 THEN suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 15 THEN suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 7 THEN suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 60 THEN suborder_quantity ELSE 0 END) AS sales_last_60_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 90 THEN suborder_quantity ELSE 0 END) AS sales_last_90_days, SUM(CASE WHEN CURRENT_DATE - order_date <= 180 THEN suborder_quantity ELSE 0 END) AS sales_last_180_days, CASE WHEN f.total_days_sold = 0 THEN SUM(suborder_quantity) ELSE SUM(suborder_quantity) / f.total_days_sold END AS natural_ros FROM knot_group_data k JOIN first_order_dates f ON k.sku_group = f.sku_group GROUP BY k.sku_group, f.first_order_date, f.last_order_date, f.days_since_first_order, f.days_since_last_order, f.total_days_sold ), enhanced_total_sales AS ( SELECT *, GREATEST( sales_first_30_days / 30, sales_last_30_days / 30, natural_ros ) AS max_first_30_last_30_natural_ros, GREATEST( sales_first_30_days / 30, sales_last_30_days / 30, natural_ros, sales_first_7_days / 7 ) AS max_first_30_last_30_natural_ros_first_7_days, CASE WHEN total_sales = 0 THEN 0 ELSE (total_returns / total_sales) * 100 END AS average_return_since_first_order, CASE WHEN GREATEST( sales_first_30_days / 30, sales_last_30_days / 30, natural_ros ) > 5 THEN GREATEST( sales_first_30_days / 30, sales_last_30_days / 30, natural_ros ) WHEN GREATEST( sales_first_30_days / 30, sales_last_30_days / 30, natural_ros ) < 5 AND (sales_first_7_days / 7) > 10 THEN sales_first_7_days / 7 WHEN total_sales > 800 THEN GREATEST(natural_ros, sales_last_7_days / 7) ELSE natural_ros END AS final_ros FROM total_sales ), inventory_pivot AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, SUM(OPENING_INVENTORY) AS sellable_inventory, SUM(CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' THEN OPENING_INVENTORY ELSE 0 END) AS XS_units, SUM(CASE WHEN SIZE = \'S\' OR SIZE = \'30\' THEN OPENING_INVENTORY ELSE 0 END) AS S_units, SUM(CASE WHEN SIZE = \'M\' OR SIZE = \'32\' THEN OPENING_INVENTORY ELSE 0 END) AS M_units, SUM(CASE WHEN SIZE = \'L\' OR SIZE = \'34\' THEN OPENING_INVENTORY ELSE 0 END) AS L_units, SUM(CASE WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN OPENING_INVENTORY ELSE 0 END) AS XL_units, SUM(CASE WHEN SIZE IN (\'XXL\', \'2XL\', \'38\') THEN OPENING_INVENTORY ELSE 0 END) AS XXL_units, SUM(CASE WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN OPENING_INVENTORY ELSE 0 END) AS XL3_units, SUM(CASE WHEN SIZE = \'4XL\' OR SIZE = \'42\' THEN OPENING_INVENTORY ELSE 0 END) AS XL4_units, SUM(CASE WHEN SIZE = \'5XL\' OR SIZE = \'44\' THEN OPENING_INVENTORY ELSE 0 END) AS XL5_units, SUM(CASE WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN OPENING_INVENTORY ELSE 0 END) AS XL6_units, SUM(CASE WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN OPENING_INVENTORY ELSE 0 END) AS XL7_units, SUM(CASE WHEN SIZE = \'8XL\' OR SIZE = \'50\' THEN OPENING_INVENTORY ELSE 0 END) AS XL8_units, SUM(CASE WHEN SIZE IS NULL THEN OPENING_INVENTORY ELSE 0 END) AS NA_units, SUM(CASE WHEN OPENING_INVENTORY > 0 THEN 1 ELSE 0 END) AS num_size_available FROM snitch_db.maplemonk.knot_inventory_report WHERE DATE = CURRENT_DATE GROUP BY SKU_GROUP ), availability_master_v2 AS ( SELECT * FROM snitch_db.maplemonk.availability_master_v2 ), metafields_data AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, TITLE, PRINT_DESIGN, COLLAR_NEW, MATERIAL_NEW, FIT, COLOR, SLEEVE_TYPE FROM snitch_db.maplemonk.metafields_data ), -- 🆕 Category Sales Ranking CTE category_sales_ranked AS ( SELECT c.CATEGORY, e.sku_group, e.total_sales, SUM(e.total_sales) OVER (PARTITION BY c.CATEGORY) AS category_total_sales, SUM(e.total_sales) OVER ( PARTITION BY c.CATEGORY ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_sales FROM enhanced_total_sales e LEFT JOIN availability_master_v2 c ON e.sku_group = c.sku_group ), -- 🆕 Category Pareto CTE category_pareto AS ( SELECT *, DIV0(cumulative_sales, category_total_sales) * 100 AS cumulative_sales_pct, CASE WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 40 THEN \'Top 40%\' WHEN DIV0(cumulative_sales, category_total_sales) * 100 <= 80 THEN \'40-80%\' ELSE \'Bottom 20%\' END AS pareto_segment FROM category_sales_ranked ), knot_base AS ( SELECT SKU_GROUP, CUT_SIZE_FLAG, DAYS_SINCE_FIRST_ORDER, DAYS_SINCE_LAST_ORDER, CUMULATIVE_SALES_PCT, PARETO_SEGMENT FROM snitch_db.maplemonk.knot_master ), production_base AS ( SELECT * FROM ( SELECT ADJUSTED_SKU AS SKU_GROUP, STATUS, REVISED_DELIVERY_DATE, PROJ_QTY, COALESCE(CUT_QTY, 0) AS CUT_QTY, ROW_NUMBER() OVER (PARTITION BY ADJUSTED_SKU, STATUS ORDER BY 1 DESC) AS rn FROM snitch_db.maplemonk.production_data WHERE STATUS = \'Active\' ) WHERE rn = 1 ), pullback_scoring AS ( SELECT s.SKU_GROUP, p.STATUS, p.REVISED_DELIVERY_DATE, p.PROJ_QTY, p.CUT_QTY, -- Score logic CASE WHEN s.CUT_SIZE_FLAG = \'Cut Size\' THEN 5 ELSE 0 END AS score_cut_size, CASE WHEN s.PARETO_SEGMENT = \'Bottom 20%\' THEN 5 WHEN s.PARETO_SEGMENT = \'40-80%\' THEN 2.5 ELSE 0 END AS score_pareto, CASE WHEN s.DAYS_SINCE_FIRST_ORDER > 100 THEN 5 WHEN s.DAYS_SINCE_FIRST_ORDER >= 50 THEN 2.5 WHEN s.DAYS_SINCE_FIRST_ORDER >= 30 THEN 1.5 ELSE 0 END AS score_first_order, CASE WHEN s.DAYS_SINCE_LAST_ORDER > 45 THEN 5 WHEN s.DAYS_SINCE_LAST_ORDER >= 30 THEN 2.5 WHEN s.DAYS_SINCE_LAST_ORDER >= 15 THEN 1.5 ELSE 0 END AS score_last_order FROM knot_base s LEFT JOIN production_base p ON s.SKU_GROUP = p.SKU_GROUP ), pullback_final AS ( SELECT *, ROUND(score_cut_size + score_pareto + score_first_order + score_last_order, 2) AS total_score, CASE WHEN score_cut_size + score_pareto + score_first_order + score_last_order <= 6 THEN \'Good - No Pullback\' WHEN score_cut_size + score_pareto + score_first_order + score_last_order <= 11 THEN \'Low - Consider\' WHEN score_cut_size + score_pareto + score_first_order + score_last_order <= 16 THEN \'Mid - Consider\' ELSE \'High - Pullback\' END AS pullback_decision, DATEDIFF(\'DAY\', CURRENT_DATE, REVISED_DELIVERY_DATE) AS Days_to_inward, FROM pullback_scoring ), add_remark AS ( SELECT *, CASE WHEN pullback_decision IN (\'Low - Consider\', \'Mid - Consider\') THEN -- Use CASE + SORT logic manually since Snowflake doesn’t support complex LISTAGG inside SELECT CASE WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_pareto >= GREATEST(score_first_order, score_last_order) THEN \'Cut Size, Low Pareto\' WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_first_order >= GREATEST(score_pareto, score_last_order) THEN \'Cut Size, Old First Order\' WHEN score_cut_size >= GREATEST(score_pareto, score_first_order, score_last_order) AND score_last_order >= GREATEST(score_pareto, score_first_order) THEN \'Cut Size, No Recent Sale\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_cut_size >= GREATEST(score_first_order, score_last_order) THEN \'Low Pareto, Cut Size\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_first_order >= GREATEST(score_cut_size, score_last_order) THEN \'Low Pareto, Old First Order\' WHEN score_pareto >= GREATEST(score_cut_size, score_first_order, score_last_order) AND score_last_order >= GREATEST(score_cut_size, score_first_order) THEN \'Low Pareto, No Recent Sale\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_cut_size >= GREATEST(score_pareto, score_last_order) THEN \'Old First Order, Cut Size\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_pareto >= GREATEST(score_cut_size, score_last_order) THEN \'Old First Order, Low Pareto\' WHEN score_first_order >= GREATEST(score_cut_size, score_pareto, score_last_order) AND score_last_order >= GREATEST(score_cut_size, score_pareto) THEN \'Old First Order, No Recent Sale\' ELSE \'No Recent Sale, Cut Size\' END ELSE NULL END AS sub_remark FROM pullback_final ) SELECT a.*, i10.opening_inventory_first_10_days, b.SELLABLE_INVENTORY, b.XS_UNITS, b.S_UNITS, b.M_UNITS, b.L_UNITS, b.XL_UNITS, b.XXL_UNITS, b.XL3_UNITS, b.XL4_UNITS, b.XL5_UNITS, b.XL6_UNITS, b.XL7_UNITS, b.XL8_UNITS, b.NA_UNITS, b.NUM_SIZE_AVAILABLE, CASE WHEN (CASE WHEN b.M_units > 0 THEN 1 ELSE 0 END + CASE WHEN b.L_units > 0 THEN 1 ELSE 0 END + CASE WHEN b.XL_units > 0 THEN 1 ELSE 0 END) < 3 THEN \'Cut Size\' ELSE \'Full Size\' END AS Cut_Size_Flag, DIV0((a.total_sales - a.total_returns), (a.total_sales - a.total_returns + b.sellable_inventory)) * 100 AS Sell_through, DIV0(b.sellable_inventory, DIV0(a.sales_last_30_days, 30)) AS DOI, c.PRODUCT_NAME, c.CATEGORY, c.SKU_CLASS, c.SELLABLE_INVENTORY AS warehouse_inventory, c.XS_UNITS AS warehouse_XS_UNITS, c.S_UNITS AS warehouse_S_UNITS, c.M_UNITS AS warehouse_M_UNITS, c.L_UNITS AS warehouse_L_UNITS, c.XL_UNITS AS warehouse_XL_UNITS, c.XXL_UNITS AS warehouse_XXL_UNITS, c.XL3_UNITS AS warehouse_XL3_UNITS, c.XL4_UNITS AS warehouse_XL4_UNITS, c.XL5_UNITS AS warehouse_XL5_UNITS, c.XL6_UNITS AS warehouse_XL6_UNITS, c.XL7_UNITS AS warehouse_XL7_UNITS, c.XL8_UNITS AS warehouse_XL8_UNITS, c.NA_UNITS AS warehouse_NA_UNITS, c.NUM_SIZE_AVAILABLE AS warehouse_NUM_SIZE_AVAILABLE, d.STR_DAY_7, d.STR_DAY_15, d.STR_DAY_30, e.TITLE, e.PRINT_DESIGN, e.COLLAR_NEW, e.MATERIAL_NEW, e.FIT, e.COLOR, e.SLEEVE_TYPE, cp.cumulative_sales_pct, cp.pareto_segment, pf.status, pf.revised_delivery_date, pf.proj_qty, pf.cut_qty, pf.score_cut_size, pf.score_pareto, pf.score_first_order, pf.score_last_order, pf.total_score, pf.pullback_decision, pf.Days_to_inward, ar.sub_remark FROM enhanced_total_sales a LEFT JOIN inventory_pivot b ON a.sku_group = b.sku_group LEFT JOIN availability_master_v2 c ON a.sku_group = c.sku_group LEFT JOIN str_final d ON a.sku_group = d.sku_group LEFT JOIN metafields_data e ON a.sku_group = e.sku_group LEFT JOIN inventory_first_10_days i10 ON a.sku_group = i10.sku_group LEFT JOIN category_pareto cp ON a.sku_group = cp.sku_group AND c.CATEGORY = cp.CATEGORY LEFT JOIN pullback_final pf ON COALESCE(a.sku_group, b.sku_group) = pf.sku_group left join add_remark ar on COALESCE(a.sku_group, b.sku_group)= ar.sku_group ORDER BY a.total_sales DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            